		visit(v, node.AsteriskToken) ||
		visit(v, node.name) ||
		visitNodeList(v, node.TypeParameters) ||
		visitNodeList(v, node.Parameters) ||
		visit(v, node.Type) ||
		visit(v, node.FullSignature) ||
		visit(v, node.Body)
